  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  duration_ms: number;
 72→  duration_api_ms: number;
 73→  is_error: boolean;
 74→  num_turns: number;
 75→}
 76→
 77→/**
 78→ * Claude is requesting permission to execute a tool. The dashboard must
 79→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 80→ *
 81→ * Wire format uses a nested `request` object with `request_id` at the
 82→ * top level for correlation (matches Companion protocol docs).
 83→ */
 84→export interface ClaudeControlRequest {
 85→  type: "control_request";
 86→  request_id: string;
 87→  request: {
 88→    subtype: "can_use_tool";
 89→    tool_name: string;
 90→    input: Record<string, unknown>;
 91→    tool_use_id?: string;
 92→    description?: string;
 93→  };
 94→  session_id?: string;
 95→}
 96→
 97→/**
 98→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 99→ * the signal that the CLI is ready to receive the first user prompt.
100→ */
101→export interface ClaudeSystemHook {
102→  type: "system";
103→  subtype: "hook_started" | "hook_response";
104→  session_id?: string;
105→}
106→
107→/** Discriminated union of all known Claude NDJSON message shapes. */
108→export type ClaudeMessage =
109→  | ClaudeSystemInit
110→  | ClaudeAssistant
111→  | ClaudeResult
112→  | ClaudeControlRequest
113→  | ClaudeSystemHook
114→  | { type: string; subtype?: string; [key: string]: unknown };
115→
116→// ── Browser ↔ Server messages ─────────────────────────────────────────────
117→
118→/** Browser asks the server to spawn a new Claude CLI process. */
119→export interface BrowserSpawn {
120→  type: "spawn";
121→  prompt: string;
122→}
123→
124→/** Browser sends a follow-up message to an already-running Claude session. */
125→export interface BrowserSendMessage {
126→  type: "send_message";
127→  agentId: string;
128→  content: string;
129→}
130→
131→/** Browser responds to a tool approval request (allow or deny). */
132→export interface BrowserControlResponse {
133→  type: "control_response";
134→  agentId: string;
135→  request_id: string;
136→  allow: boolean;
137→}
138→
139→/** Browser asks the server to kill a running agent's tmux session + CLI. */
140→export interface BrowserKillAgent {
141→  type: "kill_agent";
142→  agentId: string;
143→}
144→
145→/** Browser asks the server to permanently delete an agent. */
146→export interface BrowserDeleteAgent {
147→  type: "delete_agent";
148→  agentId: string;
149→}
150→
151→/** Browser asks the server to rename an agent. */
152→export interface BrowserRenameAgent {
153→  type: "rename_agent";
154→  agentId: string;
155→  label: string;
156→}
157→
158→/** Browser asks the server to clear an agent's message history. */
159→export interface BrowserClearHistory {
160→  type: "clear_history";
161→  agentId: string;
162→}
163→
164→/** Browser requests message history for a specific agent (lazy loading). */
165→export interface BrowserRequestHistory {
166→  type: "request_history";
167→  agentId: string;
168→}
169→
170→/** Browser asks the server to create a new task. */
171→export interface BrowserCreateTask {
172→  type: "create_task";
173→  title: string;
174→  description: string;
175→  priority: TaskPriority;
176→}
177→
178→/** Browser asks to update a task's fields. */
179→export interface BrowserUpdateTask {
180→  type: "update_task";
181→  taskId: string;
182→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
183→}
184→
185→/** Browser asks to delete a task. */
186→export interface BrowserDeleteTask {
187→  type: "delete_task";
188→  taskId: string;
189→}
190→
191→/** Browser asks to delegate a task to a new Claude agent. */
192→export interface BrowserDelegateTask {
193→  type: "delegate_task";
194→  taskId: string;
195→}
196→
197→/** Union of all messages the browser can send to the WS server. */
198→export type BrowserMessage =
199→  | BrowserSpawn
200→  | BrowserSendMessage
201→  | BrowserControlResponse
202→  | BrowserKillAgent
203→  | BrowserDeleteAgent
204→  | BrowserRenameAgent
205→  | BrowserClearHistory
206→  | BrowserRequestHistory
207→  | BrowserCreateTask
208→  | BrowserUpdateTask
209→  | BrowserDeleteTask
210→  | BrowserDelegateTask;
211→
212→/** Server relays a raw Claude NDJSON message to the browser. */
213→export interface ServerRelay {
214→  type: "relay";
215→  agentId: string;
216→  message: ClaudeMessage;
217→}
218→
219→/** Server notifies the browser of an agent status change. */
220→export interface ServerStatus {
221→  type: "status";
222→  agentId: string;
223→  status: AgentStatus;
224→}
225→
226→/** Server reports an error (e.g. no active session, process crash). */
227→export interface ServerError {
228→  type: "error";
229→  agentId: string;
230→  error: string;
231→}
232→
233→/** Summary of an agent for the sidebar. */
234→export interface AgentInfo {
235→  agentId: string;
236→  status: AgentStatus;
237→  tmuxSession: string | null;
238→  label: string;
239→  createdAt: number;
240→}
241→
242→/** Server sends the full list of agents after every state change. */
243→export interface ServerAgentList {
244→  type: "agent_list";
245→  agents: AgentInfo[];
246→}
247→
248→/** Server confirms a new agent was spawned and assigns its ID. */
249→export interface ServerSpawned {
250→  type: "spawned";
251→  agentId: string;
252→}
253→
254→/** Server sends full message history for an agent (in response to `request_history`). */
255→export interface ServerMessageHistory {
256→  type: "message_history";
257→  agentId: string;
258→  messages: ServerMessage[];
259→}
260→
261→/** CLI WebSocket disconnected (process may have crashed or exited). */
262→export interface ServerCliDisconnected {
263→  type: "cli_disconnected";
264→  agentId: string;
265→}
266→
267→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
268→export interface ServerCliConnected {
269→  type: "cli_connected";
270→  agentId: string;
271→}
272→
273→/** Server confirms message history was cleared for an agent. */
274→export interface ServerHistoryCleared {
275→  type: "history_cleared";
276→  agentId: string;
277→}
278→
279→/** Server sends the full task list to the browser. */
280→export interface ServerTaskList {
281→  type: "task_list";
282→  tasks: Task[];
283→}
284→
285→/** Server confirms a task was updated. */
286→export interface ServerTaskUpdated {
287→  type: "task_updated";
288→  task: Task;
289→}
290→
291→/** Server confirms a task was deleted. */
292→export interface ServerTaskDeleted {
293→  type: "task_deleted";
294→  taskId: string;
295→}
296→
297→/** Union of all messages the WS server can send to the browser. */
298→export type ServerMessage =
299→  | ServerRelay
300→  | ServerStatus
301→  | ServerError
302→  | ServerAgentList
303→  | ServerSpawned
304→  | ServerMessageHistory
305→  | ServerCliDisconnected
306→  | ServerCliConnected
307→  | ServerHistoryCleared
308→  | ServerTaskList
309→  | ServerTaskUpdated
310→  | ServerTaskDeleted;
311→
312→// ── UI state ──────────────────────────────────────────────────────────────
313→
314→/**
315→ * Lifecycle states of the Claude agent process:
316→ * - `idle`      — no process running, ready to spawn
317→ * - `spawning`  — process launched, waiting for CLI to connect via WS
318→ * - `connected` — CLI connected and `system/init` received
319→ * - `thinking`  — waiting for assistant response
320→ * - `done`      — `result` message received, process finished
321→ * - `error`     — process crashed or unexpected failure
322→ */
323→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
324→
325→export type ChatMessageRole = "user" | "assistant" | "system";
326→
327→/**
328→ * A single entry in the chat message list. System messages include
329→ * session init info and result summaries. Messages with a `controlRequest`
330→ * are rendered as tool-approval cards instead of plain bubbles.
331→ */
332→/** A single option in an AskUserQuestion question. */
333→export interface UserQuestionOption {
334→  label: string;
335→  description?: string;
336→}
337→
338→/** A single question from AskUserQuestion. */
339→export interface UserQuestion {
340→  question: string;
341→  header?: string;
342→  options: UserQuestionOption[];
343→  multiSelect: boolean;
344→}
345→
346→/** Info about a single tool_use block in an assistant message. */
347→export interface ToolCallInfo {
348→  name: string;
349→  toolUseId?: string;
350→}
351→
352→export interface ChatMessage {
353→  id: string;
354→  role: ChatMessageRole;
355→  content: string;
356→  timestamp: number;
357→  /** Present when this message represents a tool approval request. */
358→  controlRequest?: {
359→    id: string;
360→    tool_name: string;
361→    input: Record<string, unknown>;
362→    /** Set to true after the user allows or denies. */
363→    resolved?: boolean;
364→  };
365→  /** Present when this message is an AskUserQuestion control request. */
366→  userQuestion?: {
367→    requestId: string;
368→    questions: UserQuestion[];
369→    resolved?: boolean;
370→  };
371→  /** Tool calls found in this assistant message. */
372→  toolCalls?: ToolCallInfo[];
373→  /** True when this message has only tool_use/tool_result blocks and no text. */
374→  isToolOnly?: boolean;
375→}
376→
377→// ── Task system ──────────────────────────────────────────────────────────
378→
379→export type TaskStatus = "todo" | "in-progress" | "done";
380→export type TaskPriority = "low" | "medium" | "high" | "urgent";
381→
382→/** A user-created task, optionally linked to a Claude agent. */
383→export interface Task {
384→  id: string;
385→  title: string;
386→  description: string;
387→  status: TaskStatus;
388→  priority: TaskPriority;
389→  /** If delegated, the agentId of the spawned Claude agent. */
390→  agentId: string | null;
391→  createdAt: number;
392→  updatedAt: number;
393→}
